        add(reasons, component + '_complete_view_requires_current_facts_witness')
    records = view.get('givens')
    boundaries = view.get('boundaries')
    if type(records) is not list or type(boundaries) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['explicit_legal_channels_unread'])
    basis = {'s151_b': 'exact_s151_b', 's151_b_applies': 'exact_s151_b_applies', 's151_c_applies': 'exact_s151_c_applies', 's152_c_1': 'exact_s152_c_1', 's63_f_1_A': 'exact_s63_f_1_A', 's63_f_1_B': 'exact_s63_f_1_B'}
    seen = set()
    for record in records:
        if not support(witnesses, record, public, True):
            complete = False
            continue
        name = record.get('predicate')
        taxpayer = record.get('taxpayer')
        other = record.get('other_person')
        amount = record.get('amount')
        year = record.get('year')
        polarity = record.get('polarity')
        if name not in basis or record.get('source_basis') != basis[name] or type(taxpayer) is not str or type(year) is not int or polarity not in ('positive', 'negative'):
            complete = False
            continue
        if name == 's151_b':
            args = [taxpayer, amount, year]
            valid = type(amount) in (int, float) and other is None
        elif name == 's63_f_1_A':
            args = [taxpayer, year]
            valid = other is None and amount is None
        else:
            args = [taxpayer, other, year]
            if name == 's152_c_1':
                args = [other, taxpayer, year]
            valid = type(other) is str and amount is None
        if not valid or not valid_given(name, args):
            complete = False
            continue
        if is_target_given(kernel, name):
            complete = False
            add(reasons, 'target_legal_query_cannot_be_reasserted_as_fact')
            continue
        key = (name, tuple(args), polarity)
        if key not in seen:
            seen.add(key)
            row = {'predicate': name, 'arguments': args}
            add(negatives if polarity == 'negative' else facts, row)
    for record in boundaries:
        if not support(witnesses, record, public, True) or record.get('kind') not in ('section151_general', 'section151_d', 'section151_other', 'section63_f_other'):
            complete = False
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
