shared_helpers:
def query_rows(kernel):
    rows = kernel.get('native_query') if type(kernel) is dict else None
    return rows if type(rows) is list else []

def query_names(kernel):
    result = []
    for row in query_rows(kernel):
        name = row.get('predicate') if type(row) is dict else None
        if type(name) is str and name not in result:
            result.append(name)
    return result

def query_args(kernel, predicate):
    for row in query_rows(kernel):
        if type(row) is dict and row.get('predicate') == predicate and (type(row.get('arguments')) is list):
            return list(row.get('arguments'))
    return []

def add(rows, value):
    if value not in rows:
        rows.append(value)

def put(rows, predicate, arguments):
    add(rows, {'predicate': predicate, 'arguments': arguments})

def checked(obj, public, facts_only):
    rows = obj.get('witnesses') if type(obj) is dict else None
    if type(rows) is not list or len(rows) == 0:
        return None
    result = []
    for row in rows:
        if type(row) is not dict:
            return None
        field = row.get('field')
        quote = row.get('quote')
        text = public.get(field)
        if field not in ('facts', 'question') or type(quote) is not str or (not quote) or (type(text) is not str) or (quote not in text):
            return None
        if facts_only and field != 'facts':
            return None
        add(result, {'field': field, 'quote': quote})
    return result

def support(target, obj, public, facts_only):
    rows = checked(obj, public, facts_only)
    if rows is None:
        return False
    for row in rows:
        add(target, row)
    return True

def part(facts, negatives, witnesses, complete, reasons):
    return {'facts': facts, 'negative_givens': negatives, 'witnesses': witnesses, 'complete': complete, 'reasons': reasons}

def target_service(kernel):
    for name in ('s3306_c_10_A', 's3306_c_21', 's3306_c_5', 's3306_c_2', 's3306_c_1'):
        args = query_args(kernel, name)
        if len(args) > 0 and type(args[0]) is str:
            return args[0]
    args = query_args(kernel, 's3306_b')
    if len(args) > 2 and type(args[2]) is str:
        return args[2]
    args = query_args(kernel, 's3306_b_10_A')
    if len(args) > 1 and type(args[1]) is str:
        return args[1]
    return None

def target_payment(kernel):
    args = query_args(kernel, 's3306_b')
    if len(args) > 1 and type(args[1]) is str:
        return args[1]
    args = query_args(kernel, 's3306_b_10_A')
    if len(args) > 0 and type(args[0]) is str:
        return args[0]
    return None

def valid_given(name, args):
    if type(args) is not list:
        return False
    if name == 's151_b':
        return len(args) == 3 and type(args[0]) is str and (type(args[1]) in (int, float)) and (type(args[2]) is int)
    if name == 's63_f_1_A':
        return len(args) == 2 and type(args[0]) is str and (type(args[1]) is int)
    if name in ('s151_b_applies', 's151_c_applies', 's152_c_1', 's63_f_1_B'):
        return len(args) == 3 and type(args[0]) is str and (type(args[1]) is str) and (type(args[2]) is int)
    return False

def is_target_given(kernel, name):
    return name in query_names(kernel)

def state_time(facts, event, record, reasons, label, allow_onset):
    form = record.get('form')
    start = record.get('start_date')
    end = record.get('end_date')
    date = record.get('as_of_date')
    if form == 'ongoing_since' and type(start) is str:
        put(facts, 'start_', [event, start])
        return True
    if form == 'closed_interval' and type(start) is str and (type(end) is str):
        put(facts, 'start_', [event, start])
        put(facts, 'end_', [event, end])
        return True
    if form == 'active_on_date' and type(date) is str:
        put(facts, 'start_', [event, date])
        put(facts, 'end_', [event, date])
        return True
    if form == 'onset_only' and allow_onset and (type(start) is str):
        put(facts, 'start_', [event, start])
        return True
    if form == 'onset_only':
        add(reasons, label + '_onset_does_not_establish_later_persistence')
    else:
        add(reasons, label + '_time_invalid')
    return False

